 rows.append({'test_id':c['test_id'],'component':c.get('component') or c['test_id'].split('-')[1],'expected_result':c['expected'],'observed_result':c['observed'],'original_source_of_expectation':'SE3110 historical report case '+c['test_id']+'; original preconditions/inputs retained in historical-resolution ledger; available SE3090 Version 3.0 is a reference with approval unconfirmed','current_implementation_evidence':[source]+c.get('evidence',[]),'failure_classification':cat,'classification_label':labels[cat],'justification':why,'recommended_action':action,'assigned_component_responsibility':c.get('assigned_responsibility','Shared; confirmation pending'),'requirement_requiring_approval':decision,'original_status':c['status'],'final_status':c['status'],'new_execution_result':'Debug reproduction/retest pending; classification does not change result','authorship':'AI-assisted audit; component assignment does not prove personal execution'})
